from sklearn.metrics import mean_absolute_percentage_error, mean_squared_error

def forecast_ols(train, target_date, use_promo=False):
    d=train.copy()
    d['t']=np.arange(len(d)) # careful t reset? Need actual t maybe continuous from original
    # better use original t included.
    d['log_sales']=np.log(d.sales_units)
    if use_promo:
        dd=d.dropna(subset=['promo_intensity'])
        try:
            model=smf.ols('log_sales ~ t + C(period_month)+promo_intensity', data=dd).fit()
            # use avg promo for month from train
            pm=train[train.period_month==target_date.month].promo_intensity.dropna()
            promo=pm.mean() if len(pm) else train.promo_intensity.mean()
            fut=pd.DataFrame({'t':[len(train)], 'period_month':[target_date.month], 'promo_intensity':[promo]})
            return float(np.exp(model.predict(fut).iloc[0]))
        except Exception:
            return np.nan
    else:
        try:
            model=smf.ols('log_sales ~ t + C(period_month)', data=d).fit()
            fut=pd.DataFrame({'t':[len(train)], 'period_month':[target_date.month]})
            return float(np.exp(model.predict(fut).iloc[0]))
        except Exception:
            return np.nan

def forecast_ets(train):
    y=train.sales_units.asfreq('MS')
    vals=[]
    for trend,seasonal in [(None,'add'),(None,'mul'),('add','add'),('add','mul')]:
        try:
            fit=ExponentialSmoothing(y, trend=trend, seasonal=seasonal, seasonal_periods=12, initialization_method='estimated').fit(optimized=True)
            vals.append(float(fit.forecast(1).iloc[0]))
        except Exception:
            pass
    return float(np.median(vals)) if vals else np.nan

def forecast_sarima(train):
    y=train.sales_units.asfreq('MS')
    vals=[]
    # use fixed few known stable 
    specs=[((0,1,1),(1,0,1,12)),((0,1,1),(0,1,0,12)),((1,1,0),(1,0,0,12)),((0,0,1),(0,1,0,12))]
    for order,seas in specs:
        try:
            res=SARIMAX(np.log(y), order=order, seasonal_order=seas, trend='c' if order[1]==0 else 'n',
                        enforce_stationarity=False, enforce_invertibility=False).fit(disp=False, maxiter=200)
            vals.append(float(np.exp(res.forecast(1).iloc[0])))
        except Exception as e:
            pass
    return float(np.median(vals)) if vals else np.nan

def forecast_seasonal_drift(train, target_date):
    # previous year's same month adjusted by trailing 3/6/12 yoy growth
    idx=target_date - pd.DateOffset(years=1)
    if idx not in train.index: return np.nan
    base=train.loc[idx,'sales_units']
    # compare last k months to same months year ago if available
    ratios=[]
    for k in [3,6,12]:
        recent=train.iloc[-k:]
        past_idx=recent.index-pd.DateOffset(years=1)
        if all(i in train.index for i in past_idx):
            ratio=recent.sales_units.sum()/train.loc[past_idx,'sales_units'].sum()
            ratios.append(ratio)
    adj=np.median(ratios) if ratios else 1.0
    return float(base*adj)

# backtest last 12 months (2025 Jan-Dec) one-step
results=[]
dates=list(df2.index)
for target in dates:
    if target < pd.Timestamp('2024-10-01'): continue # at least 24 observations?
    train=df2.loc[df2.index<target].copy()
    if len(train)<24: continue
    actual=df2.loc[target,'sales_units']
    preds={
        'ols': forecast_ols(train,target,False),
        'ols_promo_avg': forecast_ols(train,target,True),
        'ets_med': forecast_ets(train),
        'sarima_med': forecast_sarima(train),
        'seasonal_drift': forecast_seasonal_drift(train,target)
    }
    for name,p in preds.items():
        if not np.isnan(p):
            results.append({'target':target,'model':name,'pred':p,'actual':actual,'ape':abs(p-actual)/actual})
resdf=pd.DataFrame(results)
resdf.groupby('model').agg(n=('ape','count'), mape=('ape','mean'), mdape=('ape','median'), rmse=('pred', lambda s: np.sqrt(np.mean((s-resdf.loc[s.index,'actual'])**2)))).sort_values('mape')
